using System.Text;
using System.Text.RegularExpressions;

namespace Zayra.Api.Tests.Security;

/// <summary>
/// RATCHET: the product is KynexOne. No string literal in Zayra.Api that a customer can read - a PDF footer,
/// an offer-letter body, an export header, an email subject, an error message - may say "Zayra".
/// (A payslip downloaded from production ended "Generated by Zayra HRMS".)
///
/// <para>What is exempt, and why: the .NET namespace and assembly name (<c>Zayra.Api.*</c>, embedded resource
/// names, DataProtection purposes <c>Zayra.*.v1</c> - renaming a protector purpose makes every stored secret
/// undecryptable), environment-variable names, the <c>zayra:</c> row-locking tags, EF/session keys, the default
/// local database name, telemetry source names, the API hostname, and the developer-facing <c>dotnet ef</c>
/// command line. Those are listed in <see cref="InternalForms"/>; each is a technical identifier, never prose.
/// The one exported VALUE that still says Zayra is allow-listed by name in <see cref="NamedExceptions"/>.</para>
///
/// <para>Comments are not literals and are ignored. Interpolation holes (<c>{Zayra.Api.X.Y(...)}</c>) are code,
/// not text, and are ignored; text outside the holes and string literals nested inside them are checked.
/// Migrations are generated and excluded.</para>
/// </summary>
public sealed class CustomerVisibleBrandRatchetTests
{
    /// <summary>Technical identifiers that legitimately keep the old name. Each match is removed before the check.</summary>
    private static readonly (Regex Pattern, string Why)[] InternalForms =
    [
        (new Regex(@"Zayra\.[A-Za-z]", RegexOptions.Compiled),
            "namespace / assembly / issuer / embedded-resource / DataProtection purpose (Zayra.Api, Zayra.Mfa.TotpSecret.v1): renaming breaks stored secrets and resource lookup"),
        (new Regex(@"ZAYRA_(AUDIT_HMAC_SECRET|COMPANY_SCOPE_ASSERT)\b", RegexOptions.Compiled),
            "environment-variable names that deployments already set"),
        (new Regex(@"\bzayra[:\-]", RegexOptions.Compiled | RegexOptions.IgnoreCase),
            "row-locking interceptor tags (zayra:for-update) and the zayra-api health/service id"),
        (new Regex(@"__zayra\.", RegexOptions.Compiled),
            "request-scope item key"),
        (new Regex(@"Database=zayra\b", RegexOptions.Compiled),
            "default local development database name"),
        (new Regex(@"Zayra(DbContext|Api)\b", RegexOptions.Compiled),
            "type names quoted in developer-facing text"),
    ];

    /// <summary>
    /// Whole literals that are customer-visible text in an exported file but are kept on purpose.
    /// Key = the exact literal.
    /// </summary>
    private static readonly Dictionary<string, string> NamedExceptions = new(StringComparer.Ordinal)
    {
        ["ZAYRA_PAYROLL"] =
            "Oracle GL import USER_JE_SOURCE_NAME (JournalExportFormattersV1). Clients mapped this source name in their " +
            "Oracle Journal Sources; renaming it silently makes their import reject every payroll journal. Change it only " +
            "with a client-by-client cutover plan, not as a text sweep.",
    };

    [Fact]
    public void NoCustomerVisibleStringLiteral_SaysZayra()
    {
        var root = SourceRoot();
        Assert.True(root is not null, "Zayra.Api source not found next to the test binaries: the ratchet cannot run, so it fails.");

        var hits = new List<string>();
        foreach (var file in Directory.EnumerateFiles(root!, "*.cs", SearchOption.AllDirectories))
        {
            var rel = Path.GetRelativePath(root!, file).Replace('\\', '/');
            if (rel.StartsWith("Migrations/") || rel.StartsWith("obj/") || rel.StartsWith("bin/")) continue;
            foreach (var (line, text) in Violations(File.ReadAllText(file)))
                hits.Add($"{rel}:{line}: {Shorten(text)}");
        }

        Assert.True(hits.Count == 0,
            "User-visible \"Zayra\" in string literals (the product is KynexOne; change the TEXT only, never a namespace, " +
            "hostname or protector purpose - add a technical identifier to InternalForms with its reason instead):\n  " +
            string.Join("\n  ", hits));
    }

    // ── the detector is itself tested, so the ratchet cannot silently go blind ─────────────────

    [Theory]
    [InlineData("var f = \"Generated by Zayra HRMS\";", true)]
    [InlineData("var f = @\"<b>Zayra AI Workforce</b>\";", true)]
    [InlineData("var f = $\"Hello {name} from Zayra\";", true)]
    [InlineData("var f = $\"{(x ? \"Zayra HRMS\" : \"\")}\";", true)]
    [InlineData("var f = \"\"\"Zayra raw\"\"\";", true)]
    [InlineData("var f = \"zayra HRMS\";", true)]
    [InlineData("var f = \"Zayra.Api\";", false)]
    [InlineData("var f = \"Zayra.Mfa.TotpSecret.v1\";", false)]
    [InlineData("var f = $\"{Zayra.Api.Infrastructure.Payroll.IbanValidator.Describe(x)}. Enter a correct IBAN.\";", false)]
    [InlineData("// Generated by Zayra HRMS\nvar f = 1;", false)]
    [InlineData("/* Zayra */ var f = 1;", false)]
    [InlineData("/// <summary>ZayraDbContext</summary>\nvar f = 1;", false)]
    [InlineData("var f = \"ZAYRA_AUDIT_HMAC_SECRET\";", false)]
    [InlineData("var f = \"https://zayra-ai-workforce.onrender.com\";", false)]
    [InlineData("var c = 'Z'; var f = \"fine\"; // Zayra", false)]
    public void Detector_FlagsProseAndIgnoresIdentifiers(string source, bool expectViolation)
        => Assert.Equal(expectViolation, Violations(source).Any());

    [Fact]
    public void NamedExceptions_StillExistInSource_SoTheyCannotRotInTheList()
    {
        var root = SourceRoot();
        Assert.True(root is not null);
        var all = string.Concat(Directory.EnumerateFiles(root!, "*.cs", SearchOption.AllDirectories)
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}Migrations{Path.DirectorySeparatorChar}"))
            .Select(File.ReadAllText));
        foreach (var literal in NamedExceptions.Keys)
            Assert.True(all.Contains($"\"{literal}\""), $"'{literal}' is allow-listed but no longer in the source: remove it from NamedExceptions.");
    }

    // ── scanner ───────────────────────────────────────────────────────────────────────────────

    internal static IEnumerable<(int Line, string Text)> Violations(string source)
    {
        foreach (var (line, text, whole) in Literals(source))
        {
            if (NamedExceptions.ContainsKey(whole)) continue;
            var rest = text;
            foreach (var (pattern, _) in InternalForms) rest = pattern.Replace(rest, string.Empty);
            if (rest.Contains("zayra", StringComparison.OrdinalIgnoreCase)) yield return (line, text);
        }
    }

    /// <summary>Yields (line, literal text outside interpolation holes, whole literal content).</summary>
    private static IEnumerable<(int Line, string Text, string Whole)> Literals(string src)
    {
        var results = new List<(int, string, string)>();
        var n = src.Length; var i = 0; var line = 1;
        while (i < n)
        {
            var c = src[i];
            if (c == '\n') { line++; i++; continue; }
            if (c == '/' && i + 1 < n && src[i + 1] == '/') { while (i < n && src[i] != '\n') i++; continue; }
            if (c == '/' && i + 1 < n && src[i + 1] == '*')
            {
                var end = src.IndexOf("*/", i + 2, StringComparison.Ordinal);
                end = end < 0 ? n : end + 2;
                line += Count(src, i, end); i = end; continue;
            }
            if (c == '\'' )
            {
                // char literal ('x', '\n', '\'') - skip so a quote char cannot open a string
                var m = Regex.Match(src.Substring(i, Math.Min(8, n - i)), @"^'(\\.[0-9a-fA-F]*|[^'\\])'");
                if (m.Success) { i += m.Length; continue; }
                i++; continue;
            }

            // string prefix: $, @, $@, @$, and raw """
            var j = i; var interpolated = false; var verbatim = false;
            while (j < n && (src[j] == '$' || src[j] == '@')) { if (src[j] == '$') interpolated = true; else verbatim = true; j++; }
            if (j < n && src[j] == '"' && (i == 0 || !(char.IsLetterOrDigit(src[i - 1]) || src[i - 1] == '_')))
            {
                var startLine = line;
                var quotes = 0; var k = j; while (k < n && src[k] == '"') { quotes++; k++; }
                if (quotes >= 3)
                {
                    var closer = new string('"', quotes);
                    var end = src.IndexOf(closer, k, StringComparison.Ordinal); end = end < 0 ? n : end;
                    var body = src.Substring(k, end - k);
                    results.Add((startLine, interpolated ? StripHoles(body) : body, body));
                    line += Count(src, i, Math.Min(n, end + quotes)); i = Math.Min(n, end + quotes); continue;
                }
                if (quotes == 2) { i = k; continue; } // empty string ""
                // regular / verbatim / interpolated
                var text = new StringBuilder(); var whole = new StringBuilder();
                k = j + 1;
                while (k < n)
                {
                    var ch = src[k];
                    if (verbatim && ch == '"') { if (k + 1 < n && src[k + 1] == '"') { text.Append('"'); whole.Append('"'); k += 2; continue; } break; }
                    if (!verbatim && ch == '\\') { if (k + 1 < n) { text.Append(src[k + 1]); whole.Append(src[k + 1]); } k += 2; continue; }
                    if (!verbatim && ch == '"') break;
                    if (!verbatim && ch == '\n') break; // unterminated: stay in sync
                    if (interpolated && ch == '{')
                    {
                        if (k + 1 < n && src[k + 1] == '{') { text.Append('{'); whole.Append("{{"); k += 2; continue; }
                        var depth = 1; whole.Append('{'); k++;
                        while (k < n && depth > 0)
                        {
                            var h = src[k];
                            if (h == '"')
                            {
                                var s2 = k + 1;
                                while (s2 < n && src[s2] != '"' && src[s2] != '\n') { if (src[s2] == '\\') s2++; s2++; }
                                var inner = src.Substring(k + 1, Math.Max(0, Math.Min(s2, n) - k - 1));
                                text.Append(' ').Append(inner).Append(' '); whole.Append('"').Append(inner).Append('"');
                                k = s2 + 1; continue;
                            }
                            if (h == '{') depth++;
                            else if (h == '}') depth--;
                            if (h == '\n') line++;
                            whole.Append(h); k++;
                        }
                        continue;
                    }
                    if (ch == '\n') line++;
                    text.Append(ch); whole.Append(ch); k++;
                }
                results.Add((startLine, text.ToString(), whole.ToString()));
                i = k + 1; continue;
            }
            i++;
        }
        return results;
    }

    private static string StripHoles(string body) => Regex.Replace(body, @"\{[^{}]*\}", " ");
    private static int Count(string s, int from, int to) { var c = 0; for (var x = from; x < to && x < s.Length; x++) if (s[x] == '\n') c++; return c; }
    private static string Shorten(string t) { t = t.Replace("\n", " ").Trim(); return t.Length <= 110 ? t : t[..110] + "..."; }

    private static string? SourceRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        for (var i = 0; i < 6 && dir?.Parent is not null; i++)
        {
            dir = dir.Parent;
            var candidate = Path.Combine(dir.FullName, "Zayra.Api");
            if (Directory.Exists(candidate)) return candidate;
        }
        return null;
    }
}
